ep_metric_enrich.versaScript:
json_xml import *;
vdb import *;
http import *;
email import *;
crypto import *;
jwt import *;
time import *;
datetime import *;

let req = params;
let body = req.body ?? {};
let authCtx = req.auth ?? {};
let actor = str(authCtx.username ?? authCtx.sub ?? "system").trim();
if (actor == "") {
  actor = "system";
}
let dryRun = body.dryRun == true || req.dryRun == true;
let name = str(body.name ?? req.name ?? "").trim();

let metrics = vdb.collection("metric_points");
let rows = [];
if (name != "") {
  let lookup = metrics.find({name: {$eq: name}}, 1);
  rows = lookup.data ?? [];
}
if (leng(rows) == 0) {
  let fallback = metrics.find({}, 1);
  rows = fallback.data ?? [];
}
if (leng(rows) == 0) {
  return {ok: false, statusCode: 404, reason: "No metric point is available to enrich"};
}

let metric = rows[0];
name = str(metric.name ?? name).trim();
let value = metric.value ?? metric["kalulu-onboarding-flow"] ?? 0;
if (value == "") {
  value = 0;
}
let tags = type(metric.tags) == "object" ? metric.tags : {};
let band = "low";
if (value >= 1000) {
  band = "critical";
} else {
  if (value >= 100) {
    band = "high";
  } else {
    if (value >= 10) {
      band = "medium";
    }
  }
}

let nowTs = datetime.now().isoformat();
let enrichedTags = {
  region: str(tags.region ?? "").trim(),
  env: str(tags.env ?? "prod").trim(),
  band: band,
  enrichedAt: nowTs,
  enrichedBy: actor
};

if (dryRun) {
  return {ok: true, dryRun: true, metric: name, value: value, tags: enrichedTags};
}

let updateRes = metrics.update({name: {$eq: name}}, {tags: enrichedTags});
if (updateRes.ok == false) {
  return {ok: false, statusCode: 500, reason: updateRes.error ?? "Failed to enrich metric", metric: name, result: updateRes};
}

let runs = vdb.collection("metric_enrichment_runs");
let runId = crypto.uuid();
let runRes = runs.insert({
  runId: runId,
  name: name,
  value: value,
  band: band,
  enrichedAt: nowTs,
  enrichedBy: actor
});

return {ok: true, metric: name, value: value, band: band, updated: true, runId: runId, runRecorded: runRes.ok ?? false, tags: enrichedTags};

